    /** The index of a known theme id, or of DEFAULT. */
    static int index(String id) {
        int i = id == null ? -1 : IDS.indexOf(id);
        return i >= 0 ? i : IDS.indexOf(DEFAULT);
    }

    public static boolean known(String id) { return id != null && IDS.contains(id); }

    /** The id itself when known, otherwise DEFAULT. */
    public static String normalize(String id) { return IDS.get(index(id)); }

    public static String label(String id) { return LABELS[index(id)]; }

    /** The theme a spoken or typed name means, or null: "glacier", "Switch to Glacier" or "the original". */
    public static String fromSpoken(String words) {
        if (words == null) return null;
        String s = words.toLowerCase(java.util.Locale.ROOT).trim();
        for (int i = 0; i < IDS.size(); i++) if (s.equals(IDS.get(i))) return IDS.get(i);
        for (int i = 0; i < SPOKEN.length; i++) for (String w : SPOKEN[i]) if (s.equals(w)) return IDS.get(i);
        return null;
    }

